insert into learning.activity_delivery (
  activity_version_id, academic_year_id, curriculum_week_id, week_number, session_number, sort_order, active
)
select
  '78bc8195-9e9e-56b9-a8bb-883fea790fbf',
  academic_year.id,
  (select id from learning.curriculum_weeks where module_id = (select id from learning.modules where course_id = (select id from learning.courses where stable_key = 'ocr-level-3-it') and stable_key = 'unit-3-cyber-security') and stable_key = 'week-5'),
  5,
  2,
  0,
  true
from learning.academic_years as academic_year
where academic_year.active
  and not exists (
    select 1 from learning.activity_delivery as delivery
    where delivery.activity_version_id = '78bc8195-9e9e-56b9-a8bb-883fea790fbf'
      and delivery.academic_year_id = academic_year.id
      and delivery.group_id is null
  )
order by academic_year.code
limit 1;

